-- Source rows for production.FactTransport: the logic of the table.
-- Generated by `python -m fde render` from models/gold/production/FactTransport.sql. Do not edit: change the spec and render again.

IF SCHEMA_ID('stage') IS NULL
    EXEC('CREATE SCHEMA [stage]');
GO

CREATE OR ALTER VIEW [stage].[FactTransportSource]
AS
with

transport as (

    select * from [lh_silver].[dbo].[transportflow]

),

facility as (

    select * from [facilities].[DimFacility]

),

material as (

    select * from [production].[DimMaterial]

),

data_source as (

    select * from [facilities].[DimDataSource]

)

select
    transport.TransportFlow_BK,
    coalesce(facility.DimFacility_SK, -1) as DimFacility_SK,
    coalesce(material.DimMaterial_SK, -1) as DimMaterial_SK,
    coalesce(data_source.DimDataSource_SK, -1) as DimDataSource_SK,
    transport.TransportTo,
    transport.TransportBy,
    transport.ExportTo,
    transport.ReportingPeriod,
    transport.IsExport,
    transport.ReportingYear,
    transport.ValueTonnes
from transport
left join facility
    on facility.Facility_BK = transport.Facility_BK
left join material
    on material.Material_BK = transport.Material_BK
left join data_source
    on data_source.DataSource_BK = transport.DataSource_BK
GO
